using System;
using System.Linq;
namespace F1Manager {
public static class Patch252Tests {
    static Career Race(int round,uint seed){var s=Data.Create(0,"",seed);s.Round=round;s.Stage=Engine.Sessions(s).Length-1;Engine.PrepareWeekend(s);s.Weekend.Weather="Сухо";Engine.Start(s);s.Weekend.Live.WeatherAt=double.MaxValue;return s;}
    public static void Run(Action<bool,string> check,Action<Action,string> rejects){
        for(int round=0;round<23;round++){var s=Race(round,(uint)(25200+round));var l=s.Weekend.Live;RaceDirector.Event(s,"SC","Test",2);l.AwaitingEvent=false;for(int tick=0;tick<7;tick++)RaceDirector.Step(s,true);check(l.LapUnits==21&&l.Entries.Where(e=>!e.Dnf).All(e=>e.Lap==0),"2.5.2 SC lap is not completed before eight ticks: "+round);RaceDirector.Step(s,true);check(l.LapUnits==24&&l.Entries.Where(e=>!e.Dnf).All(e=>e.Lap==1),"2.5.2 SC completes a lap in eight ticks on circuit "+round);check(Math.Abs(l.Elapsed-Data.Tracks[round].BaseLap*1.65)<.00001,"2.5.2 SC lap is slower in simulated time on circuit "+round);}
        var c=Race(0,25241);var live=c.Weekend.Live;var own=live.Entries.First(e=>e.Team==0);double normal=RaceDirector.PitLoss(c,own,"GREEN"),vsc=RaceDirector.PitLoss(c,own,"VSC"),sc=RaceDirector.PitLoss(c,own,"SC");check(normal>vsc&&vsc>sc&&sc>10&&RaceDirector.PitLoss(c,own,"RED")==0,"2.5.2 pit lane losses differ between green, VSC, SC and red flag");
        foreach(string flag in new[]{"GREEN","SC","VSC"}){var s=Race(0,25242);var l=s.Weekend.Live;if(flag!="GREEN"){RaceDirector.Event(s,flag,"Test",5);l.AwaitingEvent=false;}var e=l.Entries.First(x=>x.Team==0);double prior=e.RaceTime;RaceDirector.StopOnTrack(s,e,18);check(e.RaceTime==prior+18&&e.TrackDelayTotal==18,"2.5.2 stationary track delay is charged in full under "+flag);double expected=RaceDirector.PitLoss(s,e,flag);Engine.Pit(s,e.Id,"H");RaceDirector.Step(s,true);check(Math.Abs(e.LastPitLoss-expected)<.00001&&e.PitTimeTotal==e.LastPitLoss,"2.5.2 pit stop books its complete flag-specific loss under "+flag);}
        var packed=Race(0,25243);var p=packed.Weekend.Live;int i=0;foreach(var e in Engine.Order(packed))e.RaceTime=i++*8;var before=Engine.Order(packed).Select(e=>e.Id).ToArray();RaceDirector.Event(packed,"SC","Test",3);p.AwaitingEvent=false;double initial=Engine.Order(packed).Last().RaceTime-Engine.Order(packed).First().RaceTime;for(int t=0;t<16;t++)RaceDirector.Step(packed,true);double after=Engine.Order(packed).Where(e=>!e.Dnf).Last().RaceTime-Engine.Order(packed).First().RaceTime;check(after<initial*.45&&Engine.Order(packed).Where(e=>!e.Dnf).Select(e=>e.Id).SequenceEqual(before.Where(id=>!p.Entries.First(e=>e.Id==id).Dnf)),"2.5.2 SC gathers the field without on-track position shuffling");
        var virtualSC=Race(0,25244);var vs=virtualSC.Weekend.Live;RaceDirector.Event(virtualSC,"VSC","Test",4);vs.AwaitingEvent=false;var list=Engine.Order(virtualSC);double gap=list[5].RaceTime-list[4].RaceTime;RaceDirector.Step(virtualSC,true);check(Math.Abs((list[5].RaceTime-list[4].RaceTime)-gap)<.00001,"2.5.2 VSC preserves gaps instead of gathering the field");
        RaceDirector.Event(c,"RED","Test",1);double time=own.RaceTime;int stops=own.Stops,scheduled=own.ScheduledStops;Engine.Pit(c,own.Id,"S");check(own.Tyre=="S"&&own.TyreWear==0&&own.RaceTime==time&&own.Stops==stops&&own.ScheduledStops==scheduled&&own.RedChanges==1,"2.5.2 red-flag tyre change costs no race time and preserves future scheduled stops");var reloaded=Engine.Deserialize(Engine.Serialize(c));check(reloaded.Weekend.Live.Flag=="RED"&&reloaded.Weekend.Live.Entries.First(e=>e.Id==own.Id).RedChanges==1,"2.5.2 red-flag preparation survives save/load");RaceDirector.Continue(c);RaceDirector.Step(c,true);check(live.Flag=="SC"&&live.FlagTicks==8&&!live.AwaitingEvent,"2.5.2 red flag resumes behind SC without a duplicate decision popup");
        var spin=Race(0,25246);var spinning=spin.Weekend.Live.Entries.First(e=>e.Team==0);spinning.TyreWear=100;spinning.DrivingMode=2;RaceDirector.Step(spin,true);check(spinning.TrackDelayTotal>=8&&spinning.Damage>0,"2.5.2 pushing exhausted tyres produces a real timed track stop");
        var pitlap=Race(5,25248);var stopper=pitlap.Weekend.Live.Entries.First(e=>e.Team==0);double fresh=RaceDirector.Pace(pitlap,stopper);Engine.Pit(pitlap,stopper.Id,"H");RaceDirector.Step(pitlap,true);check(stopper.Last>=fresh+stopper.LastPitLoss-1,"2.5.2 the recorded pit lap includes the pit stop time loss");
        var old=Race(0,25245);old.Version=6;old.Weekend.Live.DistanceReady=false;old.Weekend.Live.RaceTick=7;old.Weekend.Live.LapUnits=0;double condition=Powertrain.Car(old.Teams[0],0).Condition[0];var migration=Engine.Deserialize(Engine.Serialize(old));check(migration.Version==8&&migration.Weekend.Live.LapUnits==84&&Powertrain.Car(migration.Teams[0],0).Condition[0]==condition,"2.5.2 schema 6 migration preserves partial laps and power-unit resource");rejects(()=>RaceDirector.StopOnTrack(c,own,double.NaN),"2.5.2 invalid stationary delay is rejected");
    }
}
}
